// Renders docs/USAGE.md from the command registry. The file on disk is
// generated: run `node scripts/gen-usage.mjs` after changing COMMANDS and
// never edit it by hand.
export function renderUsage(commands) {
  const lines = [
    '<!-- generated by scripts/gen-usage.mjs — do not edit by hand -->',
    '# CLI Usage',
    '',
  ];
  for (const name of Object.keys(commands).sort()) {
    lines.push(`## ${name}`, '', commands[name].summary, '');
  }
  return lines.join('\n');
}
